import itertools

def is_costas(p):
    n = len(p)
    for d in range(1, n):
        diffs = set()
        for i in range(n - d):
            diff = p[i+d] - p[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

for p in itertools.permutations(range(6)):
    if is_costas(p):
        print(list(p))
        break
